// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Once the native commit is durable, an interrupt must neither skip the reader reset nor be lost. */
class ValueStoreInterruptedCommitTest {

	@TempDir
	File directory;

	@Test
	void anInterruptAfterTheNativeCommitStillResetsReadersAndStaysSet() throws Exception {
		try (InterruptingValueStore values = new InterruptingValueStore(new File(directory, "values"),
				new StoreProperties(directory))) {
			// Park a pooled reader on the snapshot before the commit.
			try (var reader = values.getTxnManager().createReadTxnUntracked()) {
				reader.get();
			}
			values.startTransaction(true);
			values.storeValue(SimpleValueFactory.getInstance().createLiteral("committed before the interrupt"));
			values.interruptAfterNativeCommit = true;
			try {
				values.commit();
			} catch (IOException failure) {
				// The dictionary is already durable; any reported failure must not have skipped the reset.
			}
			assertTrue(Thread.interrupted(), "the caller's interrupt is preserved");
			try (var reader = values.getTxnManager().createReadTxnUntracked()) {
				reader.get();
				assertEquals(values.lastTransactionId(), reader.nativeTransactionId(),
						"a reused reader sees the committed dictionary");
			}
		} finally {
			Thread.interrupted();
		}
	}

	private static final class InterruptingValueStore extends ValueStore implements AutoCloseable {
		volatile boolean interruptAfterNativeCommit;

		InterruptingValueStore(File directory, StoreProperties properties) throws IOException {
			super(directory, properties, new LmdbStoreConfig().setValueDBSize(32L * 1024 * 1024));
		}

		@Override
		int commitWriteTransaction(long transaction) {
			int result = super.commitWriteTransaction(transaction);
			if (interruptAfterNativeCommit) {
				interruptAfterNativeCommit = false;
				Thread.currentThread().interrupt();
			}
			return result;
		}
	}
}
